// Example values from the specifications.
var (
	cartID     = uuid.MustParse("5f6c4bde-4e2f-4a37-9a2c-1c7f0d8b9a01")
	itemID     = uuid.MustParse("0b7e3d2a-6a4f-4c1e-8f3b-2d9c5e7a1b11")
	productID  = uuid.MustParse("9a1d7c55-3e2b-4f6a-b8c4-7e5d3a2f1c01")
	itemID2    = uuid.MustParse("0b7e3d2a-6a4f-4c1e-8f3b-2d9c5e7a1b22")
	productID2 = uuid.MustParse("9a1d7c55-3e2b-4f6a-b8c4-7e5d3a2f1c02")
)

// TestProjection runs the slice's specifications: the given events through
// the projection, then the rows the query returns.
func TestProjection(t *testing.T) {
	tests := []struct {
		name  string
		given []eventsourcing.Event
		want  []Row
		skip  string
	}{
		{
			name: "spec: Cart Items - Added items are listed",
			// Note: CartCreated is left out: the projection does not handle it.
			given: []eventsourcing.Event{
				&events.ItemAdded{CartID: cartID, ItemID: itemID, ProductID: productID, Description: "Espresso beans", Price: 12.5},
				&events.ItemAdded{CartID: cartID, ItemID: itemID2, ProductID: productID2, Description: "Milk frother", Price: 39.95},
			},
			want: []Row{
				{CartID: cartID, ItemID: itemID, ProductID: productID, Description: "Espresso beans", Price: 12.5},
				{CartID: cartID, ItemID: itemID2, ProductID: productID2, Description: "Milk frother", Price: 39.95},
			},
		},
		{
			name: "spec: Cart Items - A removed item is no longer listed",
			given: []eventsourcing.Event{
				&events.ItemAdded{CartID: cartID, ItemID: itemID, ProductID: productID, Description: "Espresso beans", Price: 12.5},
				&events.ItemAdded{CartID: cartID, ItemID: itemID2, ProductID: productID2, Description: "Milk frother", Price: 39.95},
				&events.ItemRemoved{CartID: cartID, ItemID: itemID},
			},
			want: []Row{
				{CartID: cartID, ItemID: itemID2, ProductID: productID2, Description: "Milk frother", Price: 39.95},
			},
		},
		{
			name: "spec: Cart Items - A cleared cart lists no items",
			given: []eventsourcing.Event{
				&events.ItemAdded{CartID: cartID, ItemID: itemID, ProductID: productID, Description: "Espresso beans", Price: 12.5},
				&events.CartCleared{CartID: cartID},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if tt.skip != "" {
				t.Skip("TODO: " + tt.skip)
			}
			m := NewCartItems()
			p := NewProjection(m)
			for _, e := range tt.given {
				if err := p.Handler.Handle(t.Context(), e); err != nil {
					t.Fatalf("handle %s: %v", e.EventType(), err)
				}
			}

			got, err := NewQueryHandler(m).HandleQuery(t.Context(), Query{})
			if err != nil {
				t.Fatalf("query: %v", err)
			}
			if len(got) == 0 && len(tt.want) == 0 {
				return
			}
			slices.SortFunc(tt.want, compareRows)
			gotJSON, _ := json.Marshal(got)
			wantJSON, _ := json.Marshal(tt.want)
			if !bytes.Equal(gotJSON, wantJSON) {
				t.Errorf("rows = %s, want %s", gotJSON, wantJSON)
			}
		})
	}
}
